// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// A node shows how many of its links are not loaded yet ("+10"); pressing it, like expanding again, loads the next
// ones instead of the same ones.
const REPOSITORY_ID = uniqueRepositoryId('graph-paging');
const HUB = 'http://example.org/paging/hub';
const DATA = `
@prefix ex: <http://example.org/paging/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
ex:hub rdfs:label "Hub" ; a ex:Hub .
${Array.from({ length: 90 }, (_, index) => `ex:hub ex:has ex:item${index} .`).join('\n')}
`;

test.beforeAll(async ({ request }) => {
    const repositoryUrl = `${serverBaseUrl()}/repositories/${REPOSITORY_ID}`;
    const created = await request.put(repositoryUrl, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Graph paging')
    });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${repositoryUrl}/statements`, {
        headers: { 'Content-Type': 'text/turtle' },
        data: DATA
    });
    expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test('a node shows the links that are not loaded, and pressing it loads the next ones', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(`${repositoryPageUrl(REPOSITORY_ID, 'explore')}?resource=${encodeURIComponent(`<${HUB}>`)}`);
    await waitForRoute(page, 'explore');
    await page.getByRole('button', { name: 'Add to graph' }).first().click();
    await page.getByRole('link', { name: 'Open graph' }).click();
    await waitForRoute(page, 'graph');

    const explorer = page.locator('.graph-explorer');
    const hub = explorer.locator('.graph-node').filter({ has: page.locator('text', { hasText: 'Hub' }) }).first();
    await expect(hub).toBeAttached({ timeout: 30000 });
    // Expand loads 80 statements per direction: the label, the type and 78 links.
    await expect(explorer.locator('.graph-stats')).toHaveText('79 nodes · 78 links');
    await expect(hub.locator('.node-more text')).toHaveText('+12');

    await hub.locator('.node-more').click();
    await expect(explorer.locator('.graph-stats')).toHaveText('91 nodes · 90 links', { timeout: 30000 });
    await expect(hub.locator('.node-more')).toHaveCount(0);

    await hub.dblclick();
    await expect(explorer.locator('.status-text')).toHaveText('Hub has no more links to load.');
});
